        return n & (n - 1) == 0

class Solution {
    public boolean isPowerOfTwo(int n) {
        //edge case
        if(n<=0)
            return false;
        // bitwise soln the bit representation of n and n-1 for power of two number will be always zero;
        return (n & (n-1)) ==0;

    }
}




